<article class="hmif-form-card">
    <div class="hmif-card-head"><x-filament::badge size="md" :color="match($form->status){'published'=>'success','closed'=>'danger',default=>'gray'}" :icon="match($form->status){'published'=>'heroicon-m-check-circle','closed'=>'heroicon-m-x-circle',default=>'heroicon-m-pencil'}">{{ ucfirst($form->status) }}</x-filament::badge><p class="hmif-updated">Updated {{ $form->updated_at->diffForHumans() }}</p></div>
    <div class="hmif-card-body"><h3 class="hmif-card-title">{{ filled($form->title)?$form->title:'Untitled form' }}</h3><div class="hmif-response-count"><x-filament::icon icon="heroicon-o-chart-bar" class="h-5 w-5 text-gray-400"/><span><strong>{{ number_format($form->responses_count) }}</strong> responses</span></div></div>
    <div class="hmif-card-actions"><div class="hmif-primary-actions"><x-filament::button tag="a" size="sm" icon="heroicon-m-pencil-square" :href="\App\Filament\Pages\HmifFormBuilder::getUrl(['form'=>$form->uuid])">Open</x-filament::button><x-filament::button tag="a" size="sm" color="gray" icon="heroicon-m-eye" :href="\App\Filament\Pages\HmifFormPreview::getUrl(['form'=>$form->uuid])" target="_blank">Preview</x-filament::button>@if($form->status==='published'&&$form->public_token)<x-filament::button size="sm" color="gray" icon="heroicon-m-share" type="button" data-copy-url="{{ route('hmif-forms.public.show',$form->public_token) }}" x-on:click="navigator.clipboard?navigator.clipboard.writeText($el.dataset.copyUrl).then(()=>new FilamentNotification().title('Link berhasil disalin.').success().send()):window.prompt('Salin link form:',$el.dataset.copyUrl)">Share</x-filament::button>@endif<form method="post" action="{{ route('hmif-forms.actions.duplicate',$form) }}">@csrf<x-filament::button size="sm" color="gray" icon="heroicon-m-document-duplicate" type="submit">Duplicate</x-filament::button></form></div><x-filament::modal :id="'delete-form-'.$form->id" width="md" alignment="center" icon="heroicon-o-trash" icon-color="danger" heading="Hapus Form?" :close-by-escaping="true" :close-by-clicking-away="true"><x-slot name="trigger"><x-filament::button size="sm" color="danger" outlined icon="heroicon-m-trash" type="button">Delete</x-filament::button></x-slot><div class="space-y-3 text-center text-sm text-gray-600 dark:text-gray-300"><p>Form <strong class="text-gray-950 dark:text-white">“{{ filled($form->title) ? $form->title : 'Untitled form' }}”</strong> akan dihapus.</p>@if($form->responses_count > 0)<p>Form ini memiliki <strong>{{ number_format($form->responses_count) }} response</strong>. Seluruh response dan jawaban terkait ikut dihapus.</p>@endif<p>Tindakan ini tidak dapat dibatalkan.</p></div><x-slot name="footer"><div class="flex justify-end gap-3" x-data="{ deleting: false }"><x-filament::button color="gray" type="button" x-on:click="$dispatch('close-modal', { id: 'delete-form-{{ $form->id }}' })" x-bind:disabled="deleting">Batal</x-filament::button><form method="post" action="{{ route('hmif-forms.actions.destroy',$form) }}" x-on:submit="deleting = true">@csrf @method('delete')<x-filament::button color="danger" icon="heroicon-m-trash" type="submit" x-bind:disabled="deleting"><span x-show="! deleting">Hapus Form</span><span x-show="deleting" x-cloak>Menghapus...</span></x-filament::button></form></div></x-slot></x-filament::modal></div>
